func main(cur realm) {
	r := valv3.NewValidatorProposalRequest(
		cross(cur),
		[]valv3.ValoperChange{
			valv3.NewValoperChange(address("g1f9wgcjrmta850sdudfnc498c5fu04fyyhg480v"), 0),
		},
		"Remove validator g1f9wgcjrmta850sdudfnc498c5fu04fyyhg480v",
		"Remove operator g1f9wgcjrmta850sdudfnc498c5fu04fyyhg480v from the active valset.",
	)
	pid := dao.MustCreateProposal(cross(cur), r)
	dao.MustVoteOnProposalSimple(cross(cur), int64(pid), "YES")
	dao.ExecuteProposal(cross(cur), pid)
}

